'use client';

import React from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { LayoutDashboard, PlusCircle, Settings, Activity, LogOut } from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';

export function Sidebar() {
  const pathname = usePathname();
  const { user, signOut } = useAuth();

  const links = [
    {
      label: 'Dashboard',
      href: '/dashboard',
      icon: LayoutDashboard,
      active: pathname === '/dashboard',
    },
    {
      label: 'Add Site',
      href: '/dashboard/sites/new',
      icon: PlusCircle,
      active: pathname === '/dashboard/sites/new',
    },
    {
      label: 'Settings',
      href: '/dashboard/settings',
      icon: Settings,
      active: pathname === '/dashboard/settings',
    },
  ];

  return (
    <aside className="w-64 bg-[#161B22] border-r border-[#30363D] flex flex-col justify-between flex-shrink-0 min-h-screen">
      <div>
        {/* Brand */}
        <div className="h-16 px-6 flex items-center gap-2.5 border-b border-[#30363D]">
          <div className="w-7 h-7 rounded-[6px] bg-[#00FF87]/15 border border-[#00FF87]/40 flex items-center justify-center text-[#00FF87]">
            <Activity className="h-4 w-4" />
          </div>
          <div>
            <span className="font-bold tracking-tight text-white font-mono text-base">Ping<span className="text-[#00FF87]">Watch</span></span>
            <span className="text-[10px] text-[#8B949E] block -mt-1 font-mono">Uptime Engine</span>
          </div>
        </div>

        {/* Navigation */}
        <nav className="p-4 space-y-1.5">
          {links.map((link) => {
            const Icon = link.icon;
            return (
              <Link
                key={link.href}
                href={link.href}
                className={`flex items-center gap-3 px-3 py-2.5 rounded-[6px] text-sm font-medium transition-colors ${
                  link.active
                    ? 'bg-[#00FF87]/10 text-[#00FF87] border border-[#00FF87]/30'
                    : 'text-[#8B949E] hover:text-white hover:bg-[#0D1117]'
                }`}
              >
                <Icon className={`h-4 w-4 ${link.active ? 'text-[#00FF87]' : ''}`} />
                <span>{link.label}</span>
              </Link>
            );
          })}
        </nav>
      </div>

      {/* User Section / Logout */}
      <div className="p-4 border-t border-[#30363D]">
        <div className="flex items-center justify-between mb-2">
          <div className="min-w-0 flex-1 mr-2">
            <span className="text-xs text-[#8B949E] block">Signed in as</span>
            <span className="text-xs font-mono text-white truncate block" title={user?.email}>
              {user?.email || 'Authenticated User'}
            </span>
          </div>
          <button
            onClick={() => signOut()}
            className="p-1.5 text-[#8B949E] hover:text-[#FF4D4F] hover:bg-[#FF4D4F]/10 rounded-[6px] transition-colors"
            title="Sign Out"
          >
            <LogOut className="h-4 w-4" />
          </button>
        </div>
      </div>
    </aside>
  );
}
